/* Dữ liệu 36 kế. Mỗi kế: id (số thứ tự trong 36 kế), lens (l1..l6), name, han, literal, group, story, note, mech, cond, fail, detect, confuse. */
const K = [
  {id:1, lens:"l1", name:"Man thiên quá hải", han:"瞒天过海", literal:"Giấu trời mà vượt biển", group:"Thắng chiến kế, nhóm dùng khi mình đang có ưu thế",
   story:"Năm 589, tướng Hạ Nhược Bật nhà Tùy chuẩn bị vượt Trường Giang đánh nhà Trần. Mỗi lần thay quân phòng thủ, ông cho tập trung quân rầm rộ ở bờ bắc, cờ xí rợp trời, khiến quân Trần hoảng hốt dàn trận chống đỡ. Lặp lại nhiều lần, quân Trần nhận ra đó chỉ là đổi quân nên thôi đề phòng. Đến khi quân Tùy vượt sông thật, bờ nam gần như không kịp phản ứng.",
   note:"Tên kế thường được gắn với giai thoại Đường Thái Tông sợ vượt biển, được tướng sĩ mời vào một “ngôi nhà” thực ra là chiếc thuyền đã ra khơi. Câu chuyện Hạ Nhược Bật có trong chính sử nên đáng tin hơn.",
   mech:"Giấu hành động thật bên trong một khuôn mẫu quen thuộc. Lặp lại điều bất thường cho đến khi nó thành bình thường, để đối phương tự tắt cảnh giác.",
   cond:"Có đủ thời gian để tạo thói quen. Hành động thật phải trông giống hệt những lần lặp lại. Đối phương không có lý do hay nguồn lực để kiểm tra kỹ từng lần.",
   fail:"Đối phương vẫn kiểm tra ngẫu nhiên dù tín hiệu đã quen. Lần thật có một chi tiết khác thường bị phát hiện. Hoặc chi phí duy trì vở diễn quá lớn.",
   detect:"Tự hỏi: mình đang bỏ qua điều gì chỉ vì nó đã lặp lại quá nhiều lần? Những tín hiệu khiến bạn nghĩ “lại nữa à” chính là chỗ nên kiểm tra ngẫu nhiên.",
   confuse:{id:7, text:"Cả hai đều dùng sự lặp lại. Nhưng Man thiên quá hải giấu cái thật trong cái quen, còn Vô trung sinh hữu đi từ cái giả rồi biến nó thành cái thật."}},
  {id:6, lens:"l1", name:"Dương đông kích tây", han:"声东击西", literal:"Làm ồn phía đông, đánh phía tây", group:"Thắng chiến kế, nhóm dùng khi mình đang có ưu thế",
   story:"Năm 87, Ban Siêu nhà Đông Hán đánh nước Sa Xa ở Tây Vực, vua Quy Tư đem quân lớn đến cứu. Ban Siêu giả họp tướng bàn rút lui và cố tình để tù binh trốn về báo tin. Vua Quy Tư liền chia quân đi chặn hai ngả đường rút. Ban Siêu lập tức quay lại đánh thẳng vào Sa Xa, lúc này đã mất viện binh, và giành thắng lợi.",
   note:"Cách phá kế này cũng có trong sử: khi dẹp loạn bảy nước thời Hán Cảnh Đế, quân Ngô làm ồn ở góc đông nam thành, nhưng Chu Á Phu lại tăng phòng thủ góc tây bắc. Quả nhiên quân Ngô đánh tây bắc và thất bại.",
   mech:"Tạo một mối đe dọa đủ thật ở điểm A để đối phương dồn lực về A, rồi đánh vào điểm B vừa bị bỏ trống. Mấu chốt là thời điểm: đòn nhử và đòn thật diễn ra gần như liền nhau.",
   cond:"Đòn nhử phải đủ đáng tin để đối phương phản ứng. Mình đủ cơ động để chuyển hướng nhanh. Lực lượng của đối phương có hạn, không thể canh mọi nơi.",
   fail:"Đối phương giữ lực lượng dự bị và không dồn hết theo tín hiệu ồn nhất. Hoặc họ đọc được tâm lý người nhử, như Chu Á Phu.",
   detect:"Một áp lực đột ngột và ồn ào bất thường. Trước khi dồn lực về đó, hãy hỏi: nếu mình làm vậy, chỗ nào sẽ bị bỏ trống?",
   confuse:{id:8, text:"Dương đông kích tây là một đòn nhử chớp nhoáng ngay trước đòn thật. Ám độ Trần Thương là một vỏ bọc kéo dài, và bản thân vỏ bọc đó cũng hợp lý."}},
  {id:7, lens:"l1", name:"Vô trung sinh hữu", han:"无中生有", literal:"Từ không sinh ra có", group:"Địch chiến kế, nhóm dùng khi hai bên ngang sức",
   story:"Năm 756, Trương Tuần giữ thành Ung Khâu bị Lệnh Hồ Triều vây đánh, quân trong thành cạn tên. Ban đêm, ông cho thả hàng nghìn hình nộm rơm mặc áo đen xuống chân thành. Quân vây tưởng bị đánh úp, bắn tên như mưa, và Trương Tuần thu được hàng chục vạn mũi tên. Những đêm sau ông lại thả, quân địch biết là nộm nên cười nhạo, không phòng bị. Đến lúc đó Trương Tuần thả xuống năm trăm quân cảm tử thật, đánh úp doanh trại khiến địch tan vỡ.",
   note:"",
   mech:"Kế có hai pha. Dựng lên một thứ không có thật để đối phương phản ứng, rồi khi đối phương đã kết luận “đó là giả” thì biến nó thành thật. Bản chất là khai thác chính kết luận của đối phương. Rộng hơn, đây là dùng cái giả để tạo ra một hiện thực thật.",
   cond:"Cái giả phải đủ thuyết phục ở pha đầu. Mình có lực lượng thật sẵn sàng cho pha sau. Đối phương có xu hướng tin chắc vào kết luận mình đã rút ra.",
   fail:"Đối phương không bao giờ kết luận dứt khoát, luôn xử lý mỗi tín hiệu như có thể là thật. Hoặc cái giả bị lộ quá sớm, khiến người dùng kế mất uy tín.",
   detect:"Khi bạn đã nghĩ “lần này chắc lại giả”, hãy tự hỏi: nếu lần này là thật thì thiệt hại bao nhiêu?",
   confuse:{id:29, text:"Thụ thượng khai hoa khuếch đại cái đã có: cây là thật, chỉ hoa là giả. Vô trung sinh hữu dựng lên thứ hoàn toàn chưa tồn tại."}},
  {id:8, lens:"l1", name:"Ám độ Trần Thương", han:"暗渡陈仓", literal:"Lén vượt qua Trần Thương", group:"Địch chiến kế, nhóm dùng khi hai bên ngang sức",
   story:"Năm 206 TCN, Lưu Bang bị Hạng Vũ đẩy vào đất Hán Trung. Khi đi, ông cho đốt sạn đạo để tỏ ý không quay lại. Sau đó Hàn Tín cho quân công khai sửa lại sạn đạo, một công trình đồ sộ rõ ràng sẽ mất rất lâu. Chương Hàm, tướng trấn giữ Quan Trung, tập trung theo dõi sạn đạo. Trong khi đó, quân chủ lực đi đường vòng qua Trần Thương, đánh úp và chiếm được Quan Trung.",
   note:"Tên đầy đủ của kế là “Minh tu sạn đạo, ám độ Trần Thương”: công khai sửa sạn đạo, lén vượt Trần Thương.",
   mech:"Một hành động công khai, hợp lý và kéo dài chiếm trọn sự chú ý của đối phương, trong khi con đường thật đi lối khác. Đòn nhử ở đây không phải một tiếng động thoáng qua mà là cả một “dự án” đối phương tin là kế hoạch chính.",
   cond:"Hành động công khai phải hợp lý đến mức đối phương tin đó là con đường duy nhất. Có một lối thứ hai mà đối phương không nghĩ tới hoặc coi nhẹ. Giữ được bí mật trong thời gian dài.",
   fail:"Đối phương rà soát mọi con đường có thể, thay vì chỉ canh con đường hiển nhiên. Hoặc tin tức về lối thứ hai bị lộ.",
   detect:"Khi đối thủ làm một việc quá rõ ràng và quá dễ đoán, hãy hỏi: còn con đường nào khác dẫn tới cùng mục tiêu mà mình chưa canh?",
   confuse:{id:6, text:"Dương đông kích tây là một đòn nhử chớp nhoáng ngay trước đòn thật. Ám độ Trần Thương là một vỏ bọc dài hạn, và chính vỏ bọc đó cũng có lý do tồn tại."}},
  {id:10, lens:"l1", name:"Tiếu lý tàng đao", han:"笑里藏刀", literal:"Trong nụ cười giấu dao", group:"Địch chiến kế, nhóm dùng khi hai bên ngang sức",
   story:"Năm 340 TCN, Thương Ưởng nước Tần dẫn quân đánh Ngụy. Ông viết thư cho chủ tướng Ngụy là công tử Ngang, vốn là người quen cũ, nhắc lại tình bạn và đề nghị hai bên hội đàm, uống rượu giảng hòa rồi cùng rút quân. Công tử Ngang tin lời, đến dự tiệc thì bị phục binh bắt sống. Quân Ngụy mất chủ tướng và đại bại.",
   note:"Thành ngữ “trong cười có dao” sau này được dùng để nói về Lý Nghĩa Phủ đời Đường, người bề ngoài hòa nhã nhưng lòng dạ hiểm độc.",
   mech:"Dùng thiện chí bề ngoài để đối phương tự hạ phòng bị, rồi ra tay khi họ không còn lớp bảo vệ. Biến số bị thao túng là niềm tin.",
   cond:"Có sẵn một mối quan hệ hoặc một lý do hợp lý để tỏ thiện chí. Đối phương đang mong muốn hòa hoãn. Có cơ hội để đối phương tự bước vào vị trí dễ tổn thương.",
   fail:"Đối phương tách bạch thái độ với cam kết, giữ nguyên các lớp bảo vệ dù quan hệ thân thiện đến đâu. Với người dùng kế, một khi bị lộ thì uy tín mất vĩnh viễn.",
   detect:"Nụ cười không phải dấu hiệu. Dấu hiệu là khi sự thân thiện đi kèm một đề nghị bỏ bớt lớp bảo vệ, kiểu “tin nhau mà, cần gì giấy tờ”.",
   confuse:{id:27, text:"Cả hai đều che giấu ý đồ. Tiếu lý tàng đao chủ động tạo thiện cảm để đối phương mở cửa. Giả si bất điên làm mình trông vô hại để đối phương thôi để ý."}},
  {id:27, lens:"l1", name:"Giả si bất điên", han:"假痴不癫", literal:"Giả ngây dại chứ không điên", group:"Tịnh chiến kế, nhóm dùng trong quan hệ liên minh và tranh quyền",
   story:"Năm 248, Tư Mã Ý bị Tào Sảng lấn át quyền lực nên cáo bệnh ở nhà. Khi Lý Thắng, người phe Tào Sảng, đến thăm dò, Tư Mã Ý giả run rẩy, uống cháo rơi vãi, nghe nhầm lời người nói, trông như ông già sắp chết. Tào Sảng nghe báo lại thì yên tâm. Đầu năm 249, nhân lúc Tào Sảng theo vua rời kinh đi viếng lăng Cao Bình, Tư Mã Ý phát động chính biến và nắm toàn bộ quyền lực.",
   note:"",
   mech:"Hạ thấp hình ảnh về năng lực hoặc tham vọng của mình để đối phương rút sự chú ý và cảnh giác. Bên trong vẫn tỉnh táo và chờ thời cơ.",
   cond:"Mình đang yếu thế, chưa đủ lực để đối đầu. Có thể kiên nhẫn chịu đựng lâu. Vẫn giữ được nguồn lực và các mối quan hệ ngầm.",
   fail:"Đóng vai quá lâu đến mức mất thật vị trí và đồng minh. Hoặc đối phương vẫn đề phòng dù mình tỏ ra vô hại.",
   detect:"Một người có năng lực đã được biết đến bỗng trở nên hoàn toàn vô hại. Hãy đánh giá họ theo nguồn lực và quan hệ họ còn nắm, không theo dáng vẻ họ thể hiện.",
   confuse:{id:32, text:"Hai kế đi ngược chiều nhau. Giả si bất điên giấu sức mạnh có thật. Không thành kế phô ra sức mạnh không có."}},
  {id:29, lens:"l1", name:"Thụ thượng khai hoa", han:"树上开花", literal:"Trên cây nở hoa", group:"Tịnh chiến kế, nhóm dùng trong quan hệ liên minh và tranh quyền",
   story:"Theo Tam quốc diễn nghĩa, ở trận Đương Dương, Trương Phi chỉ có khoảng hai mươi kỵ binh để chặn hậu ở cầu Trường Bản. Ông cho quân buộc cành cây vào đuôi ngựa, phóng qua lại trong rừng phía sau làm bụi tung mù mịt. Quân Tào nghi có phục binh lớn nên không dám tiến.",
   note:"Chi tiết buộc cành cây là của tiểu thuyết. Chính sử chỉ ghi Trương Phi dẫn khoảng hai mươi kỵ binh chặn hậu, đứng trên cầu quát lớn, và quân Tào không ai dám đến gần.",
   mech:"Mượn những yếu tố bên ngoài như đồng minh, danh tiếng, hình thức hay môi trường để khuếch đại vẻ ngoài về sức mạnh. Lực thật nhỏ, nhưng thế trông lớn, như buộc hoa giả lên một cái cây thật.",
   cond:"Đối phương không thể kiểm chứng ngay. Có thứ để mượn. Mục tiêu là trì hoãn hoặc răn đe, không phải đánh thật.",
   fail:"Đối phương thử thách trực tiếp, vì cái thế giả không chịu được va chạm. Kế này mua được thời gian chứ không thay thế được sức mạnh thật.",
   detect:"Hình thức hoành tráng nhưng không kiểm chứng được. Hãy làm một phép thử nhỏ và rẻ: đòi bằng chứng cụ thể, đặt một đơn hàng nhỏ, hoặc gặp trực tiếp.",
   confuse:{id:7, text:"Thụ thượng khai hoa khuếch đại cái đã có. Vô trung sinh hữu dựng lên cái hoàn toàn không có."}},
  {id:32, lens:"l1", name:"Không thành kế", han:"空城计", literal:"Kế thành trống", group:"Bại chiến kế, nhóm dùng khi mình đang thất thế",
   story:"Câu chuyện nổi tiếng nhất đến từ Tam quốc diễn nghĩa: Gia Cát Lượng ở Tây Thành gần như không còn quân, liền mở toang cổng thành và ngồi gảy đàn trên lầu. Tư Mã Ý biết Gia Cát Lượng cả đời cẩn trọng, nghi có phục binh nên rút quân.",
   note:"Các sử gia nghi ngờ chuyện Gia Cát Lượng. Tuy vậy, chính sử ghi một trường hợp tương tự: năm 219 ở Hán Thủy, Triệu Vân bị quân Tào truy đến tận doanh trại. Ông cho mở cổng, hạ cờ, ngừng trống. Quân Tào nghi có phục binh nên rút, và Triệu Vân thừa cơ đánh đuổi.",
   mech:"Khi gần như không còn lực, phô bày sự trống rỗng một cách điềm tĩnh để đối phương tự diễn giải đó là bẫy. Kế chỉ chạy được nhờ hình ảnh và uy tín mà chính người dùng kế đã tích lũy.",
   cond:"Đối phương biết rõ mình và tin mình là người thận trọng hoặc mạnh. Đối phương đa nghi và sợ rủi ro. Mình không còn lựa chọn nào tốt hơn.",
   fail:"Đối phương liều lĩnh, hoặc không biết gì về mình. Chỉ cần một toán trinh sát nhỏ thử là lộ. Đây là canh bạc, không phải chiến lược lặp lại được.",
   detect:"Đối phương đang yếu thế rõ ràng mà lại bình thản bất thường. Thay vì đoán tâm lý, hãy tìm một cách kiểm chứng rẻ.",
   confuse:{id:29, text:"Cả hai đều làm mình trông mạnh hơn. Thụ thượng khai hoa phô thêm hình thức. Không thành kế phô ra sự trống rỗng và để đối phương tự dọa mình."}},
  {id:15, lens:"l3", name:"Điệu hổ ly sơn", han:"调虎离山", literal:"Dụ hổ rời núi", group:"Công chiến kế, nhóm dùng khi chủ động tấn công",
   story:"Năm 199, Tôn Sách muốn đánh Lư Giang, nhưng thành này kiên cố và Lưu Huân giữ thành có quân mạnh. Tôn Sách bèn gửi thư lời lẽ nhún nhường kèm lễ vật, tôn Lưu Huân lên và gợi ý ông đem quân đánh Thượng Liêu, một vùng giàu có, hứa sẽ hỗ trợ. Lưu Huân mừng rỡ, dẫn quân rời thành. Tôn Sách lập tức đánh chiếm Lư Giang gần như không gặp kháng cự.",
   note:"Hình ảnh của tên kế: con hổ trên núi là chúa tể, xuống đồng bằng thì sức mạnh giảm hẳn. Kế đặt câu hỏi: đối phương mạnh nhờ bản thân họ, hay nhờ chỗ họ đang đứng?",
   mech:"Đối phương mạnh nhờ vị trí chứ không nhờ bản thân: thành lũy, sân nhà, mạng lưới quan hệ, lợi thế địa phương. Kế dụ hoặc ép họ rời vị trí đó trước khi giao tranh, hoặc tranh thủ đúng lúc vị trí bị bỏ trống.",
   cond:"Xác định đúng rằng nguồn sức mạnh của đối phương là vị trí. Có mồi đủ hấp dẫn hoặc áp lực đủ lớn để họ chịu rời đi. Mình đủ nhanh để chiếm chỗ trống, hoặc đủ mạnh ở nơi họ được kéo tới.",
   fail:"Đối phương hiểu giá trị vị trí của mình nên không rời, hoặc để lại lực lượng đủ giữ. Hoặc họ vẫn mạnh ngay cả khi ra ngoài, nghĩa là mình đã đánh giá sai nguồn sức mạnh của họ.",
   detect:"Một cơ hội hấp dẫn bất thường đòi bạn rời khỏi chỗ mình mạnh nhất: thị trường lõi, đội ngũ chủ chốt, vị trí đang nắm. Hãy hỏi: ai được lợi khi mình rời đi, và ai sẽ giữ chỗ cũ?",
   confuse:{id:6, text:"Dương đông kích tây chỉ kéo sự chú ý đi trong chốc lát để đánh chỗ trống. Điệu hổ ly sơn kéo chính lực lượng chủ chốt ra khỏi vị trí làm nên sức mạnh của nó."}},
  {id:21, lens:"l3", name:"Kim thiền thoát xác", han:"金蝉脱壳", literal:"Ve sầu vàng lột xác", group:"Hỗn chiến kế, nhóm dùng khi tình thế rối ren",
   story:"Năm 234, Gia Cát Lượng mất trong quân ở Ngũ Trượng Nguyên. Quân Thục giữ kín tin và chuẩn bị rút về. Tư Mã Ý nghe dân báo liền đem quân đuổi theo. Khương Duy bảo Dương Nghi cho quân quay cờ, đánh trống như sắp phản công. Tư Mã Ý sợ trúng kế nên rút lui, và quân Thục về nước an toàn. Người đương thời có câu: “Gia Cát chết dọa Trọng Đạt sống chạy”.",
   note:"Chi tiết đặt tượng gỗ Gia Cát Lượng ngồi trên xe là của Tam quốc diễn nghĩa. Hình ảnh của tên kế: con ve bay đi, để lại cái xác nguyên vẹn bám trên cành, ai nhìn cũng tưởng nó vẫn còn đó.",
   mech:"Rút lui hoặc chuyển hướng trong khi giữ nguyên vẻ ngoài ở vị trí cũ, để đối phương tiếp tục canh một cái vỏ rỗng. Khi họ nhận ra thì mình đã đi xa. Kế biến một cuộc rút lui thành rút lui có trật tự, không thành tháo chạy.",
   cond:"Có một cái vỏ đủ thuyết phục: tín hiệu, hình thức, hoạt động bề ngoài. Đối phương không áp sát kiểm tra. Mình đã có sẵn nơi để rút về hoặc hướng để chuyển sang.",
   fail:"Đối phương bám sát và kiểm tra thường xuyên, nên vỏ bị lộ trước khi thoát xong. Khi đó cuộc rút lui có trật tự biến thành tháo chạy, còn tệ hơn rút công khai.",
   detect:"Hoạt động bề ngoài vẫn đều đặn, nhưng những thứ khó giả như nhân sự chủ chốt, tài sản, dòng tiền đang dịch chuyển. Hãy theo dõi thứ khó giả, đừng theo dõi thứ dễ giả.",
   confuse:{id:32, text:"Không thành kế phô ra sự trống rỗng để đối phương không dám tiến vào. Kim thiền thoát xác giữ vẻ đầy đủ để đối phương không biết mình đã đi."}},
  {id:22, lens:"l3", name:"Quan môn tróc tặc", han:"关门捉贼", literal:"Đóng cửa bắt giặc", group:"Hỗn chiến kế, nhóm dùng khi tình thế rối ren",
   story:"Năm 260 TCN, ở Trường Bình, tướng Tần Bạch Khởi giả thua để quân Triệu do Triệu Quát chỉ huy hăng hái truy đuổi vào sâu. Khi quân Triệu đã vào, quân Tần cắt đứt đường lui và đường vận lương phía sau. Bị vây hơn bốn mươi ngày, quân Triệu cạn lương, Triệu Quát tử trận khi phá vây, và toàn quân đầu hàng.",
   note:"Tôn Tử cũng cảnh báo mặt trái của kế này trong thiên Quân tranh: “vi sư tất khuyết”, vây quân địch thì phải chừa một lối. Quân bị dồn vào đường cùng sẽ liều chết.",
   mech:"Khi đối phương đã lọt vào một không gian mình kiểm soát, khóa mọi lối ra để buộc họ phải chịu kết quả. Bản chất là biến một vị trí thành cái bẫy kín và giải quyết một lần, thay vì đuổi theo khi họ đã tản ra.",
   cond:"Đối phương đã ở trong vùng mình kiểm soát. Mình đủ lực bịt mọi lối. Đối phương không đủ mạnh để phá vây, và không có viện binh từ bên ngoài.",
   fail:"Dồn đối phương vào đường cùng khiến họ liều chết. Lực vây không đủ nên bị phá. Hoặc có viện binh đánh từ ngoài vào, khiến người vây trở thành người bị kẹp.",
   detect:"Đường lui của bạn dần bị đóng lại: hợp đồng ràng buộc, chi phí chuyển đổi tăng, phụ thuộc vào một bên duy nhất. Hãy hỏi định kỳ: nếu muốn rời đi lúc này, mình có đi được không?",
   confuse:{id:28, text:"Thượng ốc trừu thê dùng mồi để dụ đối phương bước lên rồi rút thang. Quan môn tróc tặc không cần mồi; nó tập trung vào việc khóa không gian khi đối phương đã ở bên trong."}},
  {id:28, lens:"l3", name:"Thượng ốc trừu thê", han:"上屋抽梯", literal:"Lên lầu rồi rút thang", group:"Tịnh chiến kế, nhóm dùng trong quan hệ liên minh và tranh quyền",
   story:"Lưu Kỳ, con trưởng của Lưu Biểu, bị mẹ kế ghen ghét và tìm cách hại. Nhiều lần anh hỏi kế Gia Cát Lượng, nhưng Lượng đều từ chối vì không muốn dính vào chuyện nhà người khác. Một hôm Lưu Kỳ mời Lượng lên lầu, rồi sai người rút thang, nói: “Giờ trên không chạm trời, dưới không chạm đất, lời ra từ miệng ông chỉ vào tai tôi.” Gia Cát Lượng bèn khuyên anh xin ra trấn thủ Giang Hạ để tránh họa.",
   note:"Kế này có hai chiều. Chiều thứ hai là tự rút thang của chính mình: năm 207 TCN ở Cự Lộc, Hạng Vũ cho đập nồi, đắm thuyền sau khi qua sông, để quân sĩ hiểu rằng không còn đường lui và phải đánh đến cùng.",
   mech:"Dụ đối phương bước lên một vị trí bằng mồi hoặc lời hứa, rồi cắt đường lui, khiến họ chỉ còn cách đi theo hướng mình định. Ở chiều ngược lại, tự cắt đường lui của chính mình để buộc bản thân và người của mình dốc toàn lực.",
   cond:"Có mồi đủ hấp dẫn để đối phương tự bước lên. Mình kiểm soát được cái thang, tức là lối lui. Với chiều tự rút thang: đội ngũ có đủ năng lực, chỉ thiếu quyết tâm.",
   fail:"Đối phương kiểm tra lối lui trước khi bước lên. Với chiều tự rút thang: nếu thất bại thì mất tất cả, nên chỉ đáng dùng khi phần thắng đủ lớn và năng lực là thật.",
   detect:"Một lời mời hấp dẫn đi kèm cam kết khó rút lại: đặt cọc lớn không hoàn, chuyển toàn bộ sang hệ thống của họ, bỏ hết lựa chọn khác. Trước khi bước lên, hãy hỏi: thang ở đâu, và ai đang giữ thang?",
   confuse:{id:22, text:"Quan môn tróc tặc khóa không gian khi đối phương đã tự lọt vào. Thượng ốc trừu thê cần mồi để đối phương tự bước lên, rồi mới rút thang."}},
  {id:3, lens:"l4", name:"Tá đao sát nhân", han:"借刀杀人", literal:"Mượn dao giết người", group:"Thắng chiến kế, nhóm dùng khi mình đang có ưu thế",
   story:"Thời Xuân Thu, Trịnh Hoàn công muốn đánh nước Cối. Ông lập danh sách những trung thần và mưu sĩ giỏi nhất của Cối, tuyên bố sẽ chia đất phong quan cho họ khi chiếm được Cối, rồi chôn danh sách ấy và lập đàn thề ở ngoài thành, như thể đã có giao ước. Vua Cối nghe tin, tưởng các bề tôi ấy phản mình, liền giết hết. Mất những người giỏi nhất, nước Cối bị Trịnh đánh chiếm dễ dàng.",
   note:"Câu chuyện được chép trong sách Hàn Phi Tử. Ở đây con dao là chính vua Cối: Trịnh không phải giết ai, chỉ cần khiến đối phương tự ra tay.",
   mech:"Dùng lực của một bên thứ ba, hoặc của chính đối phương, để gây thiệt hại cho đối phương. Mình không trực tiếp ra tay nên giữ được lực và tránh được trách nhiệm.",
   cond:"Có một bên có động cơ, hoặc có thể bị tạo ra động cơ, để ra tay. Mình kiểm soát được thông tin họ nhận. Mối liên hệ giữa mình và kết quả được giấu kín.",
   fail:"Bên thứ ba nhận ra mình bị lợi dụng và quay sang chống mình. Con dao không đi đúng hướng. Và nếu bị lộ, người mượn dao mất uy tín nặng hơn cả khi tự ra tay.",
   detect:"Bạn bỗng có động cơ mạnh để chống lại ai đó, dựa trên thông tin do một người khác đưa tới. Hãy hỏi: ai được lợi nếu mình làm điều này, và người đưa tin có lợi ích gì?",
   confuse:{id:33, text:"Phản gián kế là một công cụ cụ thể: biến kênh tin mà đối phương tin cậy thành đường dẫn thông tin sai. Tá đao sát nhân là nguyên lý rộng hơn: dùng lực của bất kỳ ai để ra tay thay mình. Phản gián thường là cách để mượn dao."}},
  {id:23, lens:"l4", name:"Viễn giao cận công", han:"远交近攻", literal:"Kết giao nước xa, đánh nước gần", group:"Hỗn chiến kế, nhóm dùng khi tình thế rối ren",
   story:"Khoảng năm 270 TCN, Phạm Thư hiến kế cho Tần Chiêu Tương vương. Tần đang định vượt qua Hàn và Ngụy để đánh nước Tề ở xa. Phạm Thư chỉ ra rằng đánh Tề thì dù thắng cũng không giữ nổi đất, chỉ làm lợi cho các nước ở giữa. Ông khuyên kết thân với nước xa và đánh nước gần, vì “được tấc đất là tấc đất của vua, được thước đất là thước đất của vua”. Tần theo kế ấy, lần lượt thôn tính các nước láng giềng.",
   note:"",
   mech:"Sắp xếp quan hệ theo khoảng cách của lợi ích: hòa hoãn với những bên ở xa, nơi tranh chấp tốn kém mà giành được cũng khó giữ; dồn lực vào bên gần, nơi giành được phần nào giữ chắc phần đó. Đồng thời ngăn các bên liên kết lại chống mình.",
   cond:"Lợi ích có tính gần xa: về địa lý, thị trường hay phân khúc. Bên xa có lý do để đứng ngoài. Mình củng cố được từng phần đã giành trước khi đi tiếp.",
   fail:"Bên xa nhận ra rằng khi mình nuốt xong các bên gần, họ sẽ là bên gần kế tiếp, và họ liên minh chống lại. Hoặc mình đánh quá nhiều bên gần cùng lúc.",
   detect:"Một bên mạnh tỏ ra rất thân thiện với bạn trong khi lần lượt thôn tính những người đứng giữa hai bên. Hãy hỏi: khi họ xong việc với những người ở giữa, mình có trở thành “nước gần” không?",
   confuse:{id:24, text:"Giả đạo phạt Quắc mượn bên thứ ba làm lối đi rồi nuốt luôn họ. Viễn giao cận công là chiến lược sắp xếp bạn và thù trong thời gian dài; quan hệ với bên xa là thật."}},
  {id:24, lens:"l4", name:"Giả đạo phạt Quắc", han:"假道伐虢", literal:"Mượn đường đánh nước Quắc", group:"Hỗn chiến kế, nhóm dùng khi tình thế rối ren",
   story:"Thời Xuân Thu, Tấn Hiến công muốn đánh nước Quắc nhưng phải đi qua nước Ngu. Ông đem ngọc bích quý và ngựa tốt tặng vua Ngu để xin mượn đường. Đại phu Cung Chi Kỳ can rằng Ngu và Quắc như môi với răng, môi hở thì răng lạnh. Vua Ngu tham quà nên không nghe. Tấn diệt Quắc, rồi trên đường về đánh luôn nước Ngu, lấy lại cả ngọc lẫn ngựa.",
   note:"Thành ngữ “môi hở răng lạnh” ra đời từ câu chuyện này, được chép trong Tả truyện.",
   mech:"Lấy danh nghĩa một mục tiêu khác để được bên thứ ba cho vào lãnh địa của họ, rồi khi đã ở bên trong thì chiếm luôn chính họ.",
   cond:"Bên thứ ba nhỏ hơn và đang bị kẹp giữa. Có lợi ích trước mắt đủ hấp dẫn để họ đồng ý. Họ không nhìn ra sự phụ thuộc giữa họ và mục tiêu được nêu ra.",
   fail:"Có người như Cung Chi Kỳ nhìn ra mối liên hệ môi răng và được lắng nghe. Hoặc bên thứ ba đặt điều kiện kiểm soát: giới hạn thời gian, phạm vi, giám sát.",
   detect:"Một bên mạnh xin “chỉ đi qua”, “chỉ dùng tạm” hạ tầng, dữ liệu hay khách hàng của bạn để làm việc khác, kèm lợi ích hậu hĩnh. Hãy hỏi: sau khi họ vào rồi, điều gì buộc họ phải rời đi?",
   confuse:{id:23, text:"Viễn giao cận công giữ quan hệ thật với bên xa trong thời gian dài. Giả đạo phạt Quắc chỉ dùng bên thứ ba như một lối đi, và lối đi ấy là mục tiêu tiếp theo."}},
  {id:33, lens:"l4", name:"Phản gián kế", han:"反间计", literal:"Dùng gián điệp của địch", group:"Bại chiến kế, nhóm dùng khi mình đang thất thế",
   story:"Năm 204 TCN, Lưu Bang bị Hạng Vũ vây ở Huỳnh Dương. Trần Bình hiến kế ly gián Hạng Vũ với mưu sĩ Phạm Tăng. Khi sứ giả của Hạng Vũ đến, Trần Bình cho bày tiệc thịnh soạn, rồi giả vờ ngạc nhiên: “Tưởng là sứ của Á phụ, hóa ra là sứ của Hạng vương”, và sai đổi sang mâm cơm đạm bạc. Sứ giả về kể lại, Hạng Vũ nghi Phạm Tăng ngầm thông với Hán, dần tước quyền ông. Phạm Tăng giận bỏ đi và mất trên đường về quê.",
   note:"Tôn Tử, trong thiên Dụng gián, gọi phản gián là dùng chính gián điệp của địch. Trong câu chuyện này, sứ giả của Hạng Vũ vô tình trở thành người mang thông tin sai về cho chủ mình.",
   mech:"Biến kênh thông tin mà đối phương tin cậy, như sứ giả, gián điệp hay người đưa tin, thành đường dẫn thông tin sai, để họ tự nghi ngờ và tự loại bỏ người của mình.",
   cond:"Đối phương có sẵn mầm nghi ngờ. Mình biết hoặc chạm tới được kênh tin mà họ tin. Thông tin sai phải khớp với nỗi lo có sẵn của họ.",
   fail:"Đối phương kiểm chứng chéo qua nhiều nguồn, hoặc giữa họ có lòng tin vững. Nếu kênh bị lộ, nó có thể bị dùng ngược lại để đưa thông tin sai về phía mình.",
   detect:"Thông tin khiến bạn nghi ngờ người thân cận lại đến qua đúng kênh mà đối phương có thể chạm tới, và khớp hoàn hảo với nỗi lo của bạn. Hãy kiểm chứng trực tiếp với người bị nghi trước khi hành động.",
   confuse:{id:3, text:"Tá đao sát nhân là nguyên lý rộng: dùng lực của người khác để ra tay. Phản gián kế là công cụ cụ thể: lợi dụng kênh tin cậy để gieo nghi kỵ trong nội bộ đối phương."}}
,
  {id:4, lens:"l2", name:"Dĩ dật đãi lao", han:"以逸待劳", literal:"Lấy nhàn chờ mệt", group:"Thắng chiến kế, nhóm dùng khi mình đang có ưu thế",
   story:"Năm 222, Lưu Bị đem đại quân đánh Đông Ngô để báo thù cho Quan Vũ. Tướng Ngô là Lục Tốn lui về giữ chỗ hiểm, nhất quyết không giao chiến suốt nhiều tháng, mặc các tướng dưới quyền nóng ruột. Quân Thục phải dựng doanh trại nối dài hàng trăm dặm trong rừng núi, mệt mỏi vì nắng nóng và hành quân xa. Đến mùa hè, khi quân Thục đã rệu rã, Lục Tốn dùng hỏa công đốt các doanh trại liền nhau, quân Thục đại bại ở Di Lăng.",
   note:"Tôn Tử viết trong thiên Quân tranh: “Dĩ cận đãi viễn, dĩ dật đãi lao, dĩ bão đãi cơ”, tức là lấy gần chờ xa, lấy nhàn chờ mệt, lấy no chờ đói.",
   mech:"Không lao vào khi đối phương đang sung sức. Để thời gian, khoảng cách và chính hoạt động của họ bào mòn họ, trong khi mình giữ sức, rồi ra đòn khi tương quan đã đổi.",
   cond:"Thời gian đứng về phía mình: hậu cần của mình gần, của họ xa. Mình chịu được áp lực phải chờ, kể cả áp lực từ người của mình. Đối phương buộc phải hành động và tiêu hao.",
   fail:"Đối phương không mệt đi mà mạnh lên theo thời gian, nhờ củng cố hoặc có viện binh. Mình chờ quá lâu đến mức nội bộ mất kiên nhẫn. Hoặc chờ thụ động mà không chuẩn bị đòn quyết định.",
   detect:"Đối phương liên tục né đối đầu dù có vẻ đủ sức, trong khi bạn đang tiêu hao nhanh hơn họ. Hãy hỏi: thời gian đang làm ai yếu đi?",
   confuse:{id:9, text:"Cách ngạn quan hỏa chờ các đối phương tự xung đột với nhau. Dĩ dật đãi lao chờ đối phương tự tiêu hao trong chính cuộc đối đầu với mình."}},
  {id:5, lens:"l2", name:"Sấn hỏa đả kiếp", han:"趁火打劫", literal:"Nhân lúc cháy nhà mà đi cướp", group:"Thắng chiến kế, nhóm dùng khi mình đang có ưu thế",
   story:"Năm 482 TCN, Ngô vương Phù Sai đem tinh binh lên phía bắc hội chư hầu ở Hoàng Trì để tranh ngôi bá chủ, trong nước chỉ còn người già yếu giữ thành. Việt vương Câu Tiễn, người đã chuẩn bị nhiều năm, nhân lúc đó đánh thẳng vào kinh đô nước Ngô và giết thái tử. Từ đó thế Ngô suy dần, và năm 473 TCN nước Việt diệt Ngô.",
   note:"Giá trị của kế không nằm ở lúc ra tay, mà ở những năm chuẩn bị trước đó. Câu Tiễn không tạo ra cơ hội, nhưng đã sẵn sàng khi nó đến.",
   mech:"Đánh vào lúc đối phương đang gặp khủng hoảng như nội loạn, thiên tai, bị bên khác tấn công hay đang chuyển giao, khi khả năng phản ứng của họ giảm mạnh. Cơ hội ngắn và không tự tạo ra được, nên mấu chốt là chuẩn bị sẵn để nắm lấy.",
   cond:"Khủng hoảng là thật và làm giảm khả năng phản ứng của đối phương. Mình đã chuẩn bị sẵn lực. Hành động đủ nhanh trước khi họ hồi phục.",
   fail:"Khủng hoảng khiến đối phương đoàn kết lại trước kẻ thù chung. Mình bị coi là kẻ cơ hội, mất chính danh và đồng minh. Hoặc ra tay khi chưa đủ lực.",
   detect:"Khi bạn đang gặp sự cố, hãy để ý những bên bỗng hoạt động mạnh: chào mời khách hàng của bạn, săn người của bạn, đề nghị mua lại giá rẻ. Kế hoạch cho khủng hoảng cần có trước khi khủng hoảng đến.",
   confuse:{id:20, text:"Sấn hỏa đả kiếp nhắm vào khủng hoảng riêng của một đối phương cụ thể. Hỗn thủy mô ngư khai thác, hoặc chủ động tạo ra, tình trạng hỗn loạn chung để chiếm những thứ chưa có chủ."}},
  {id:9, lens:"l2", name:"Cách ngạn quan hỏa", han:"隔岸观火", literal:"Đứng bờ bên kia xem lửa cháy", group:"Địch chiến kế, nhóm dùng khi hai bên ngang sức",
   story:"Năm 207, anh em Viên Thượng, Viên Hy, con của Viên Thiệu, thua trận chạy sang nương nhờ Công Tôn Khang ở Liêu Đông. Các tướng khuyên Tào Tháo đánh tiếp để diệt cả hai. Tào Tháo lại rút quân, giải thích rằng Công Tôn Khang vốn e ngại anh em họ Viên: nếu ép gấp, họ sẽ hợp sức chống mình; để yên, họ sẽ tự nghi kỵ nhau. Không lâu sau, Công Tôn Khang giết anh em họ Viên và gửi đầu đến cho Tào Tháo.",
   note:"",
   mech:"Khi các đối phương đang mâu thuẫn với nhau, đứng ngoài và không tạo áp lực, vì áp lực từ mình sẽ khiến họ đoàn kết lại. Để xung đột tự diễn ra, rồi thu lợi khi họ đã suy yếu.",
   cond:"Giữa các bên có mâu thuẫn thật. Áp lực từ bên ngoài là thứ chính giữ họ lại với nhau. Mình đủ kiên nhẫn và không để bị lôi vào cuộc.",
   fail:"Mâu thuẫn được hóa giải, họ làm hòa rồi quay sang mình. Người ngồi xem quá lâu bị coi là thờ ơ và mất đồng minh. Hoặc lửa lan sang bờ của mình.",
   detect:"Một bên mà bạn tưởng sẽ can thiệp lại im lặng đúng lúc bạn đang tranh chấp với người khác. Hãy hỏi: ai đang chờ chúng ta kiệt sức?",
   confuse:{id:4, text:"Dĩ dật đãi lao chờ đối phương tiêu hao trong cuộc đối đầu với chính mình. Cách ngạn quan hỏa đứng hẳn bên ngoài, chờ các bên khác tự làm hại nhau."}},
  {id:11, lens:"l2", name:"Lý đại đào cương", han:"李代桃僵", literal:"Cây mận chết thay cây đào", group:"Địch chiến kế, nhóm dùng khi hai bên ngang sức",
   story:"Tướng nước Tề là Điền Kỵ thường đua ngựa ăn tiền với vua Tề và các công tử, mỗi bên ba ngựa chia ba hạng. Ngựa cùng hạng của vua đều nhỉnh hơn nên Điền Kỵ hay thua. Tôn Tẫn bày cách: lấy ngựa hạ của mình đấu ngựa thượng của vua, ngựa thượng đấu ngựa trung, ngựa trung đấu ngựa hạ. Kết quả thua một, thắng hai, và Điền Kỵ thắng cả cuộc.",
   note:"Câu chuyện được chép trong Sử ký. Tên kế lấy từ một bài thơ cổ: cây mận mọc bên cây đào, sâu đến ăn rễ đào thì cây mận chết thay.",
   mech:"Chấp nhận hy sinh một phần nhỏ hoặc kém quan trọng để đổi lấy thắng lợi ở phần quan trọng hơn. Thay vì cố thắng mọi điểm, phân bổ lực theo giá trị của từng điểm và tính kết quả trên toàn cục.",
   cond:"Phân biệt rõ đâu là phần đáng giữ, đâu là phần có thể mất. Kết quả được tính trên toàn cục chứ không phải từng điểm. Mình chấp nhận được tổn thất cục bộ, kể cả về mặt tâm lý.",
   fail:"Hy sinh nhầm phần quan trọng. Hy sinh quá nhiều đến mức mất toàn cục. Khi thứ bị hy sinh là con người, những người còn lại có thể mất lòng tin vào mình.",
   detect:"Đối phương dễ dàng nhượng bộ ở nhiều điểm nhỏ. Có thể họ đang dồn lực cho điểm họ thật sự cần. Hãy hỏi: họ chịu thua ở đâu, và giữ chặt ở đâu?",
   confuse:{id:17, text:"Phao chuyên dẫn ngọc bỏ ra một thứ nhỏ làm mồi để đối phương đưa ra thứ lớn hơn. Lý đại đào cương hy sinh một phần của mình để bảo toàn phần quan trọng hơn, không cần đối phương cắn câu."}},
  {id:12, lens:"l2", name:"Thuận thủ khiên dương", han:"顺手牵羊", literal:"Tiện tay dắt dê", group:"Địch chiến kế, nhóm dùng khi hai bên ngang sức",
   story:"Năm 383, ở trận Phì Thủy, đại quân Tiền Tần của Phù Kiên đóng bên bờ sông, đối diện quân Đông Tấn ít hơn nhiều. Tướng Tấn là Tạ Huyền đề nghị quân Tần lùi lại một chút để quân Tấn qua sông quyết chiến. Phù Kiên đồng ý, định nhân lúc quân Tấn qua sông nửa chừng sẽ đánh. Nhưng khi quân Tần vừa lùi, đội hình rối loạn, hàng tướng Chu Tự trong quân Tần hô lớn rằng quân Tần đã thua. Tạ Huyền lập tức thúc quân vượt sông đánh tràn, biến một sơ hở thoáng qua thành đại thắng.",
   note:"Giải ngữ gốc của kế viết: “Vi khích tại sở tất thừa, vi lợi tại sở tất đắc”, tức là khe hở nhỏ cũng phải tận dụng, lợi nhỏ cũng phải giành lấy.",
   mech:"Luôn sẵn sàng chộp lấy những sơ hở và lợi ích nhỏ bất ngờ xuất hiện trên đường đi, miễn là không làm lệch mục tiêu chính. Nhiều lợi nhỏ cộng lại, hoặc một sơ hở nhỏ đúng lúc, có thể thành lợi thế lớn.",
   cond:"Mình đủ linh hoạt và có lực rảnh để hành động ngay. Lợi nhỏ không kéo mình khỏi mục tiêu chính. Luôn quan sát để thấy sơ hở khi nó vừa xuất hiện.",
   fail:"Mải nhặt lợi nhỏ mà quên mục tiêu lớn, hoặc cắn phải mồi nhử của đối phương. Lực bị phân tán vào quá nhiều việc nhỏ.",
   detect:"Phía bạn có những sơ hở nhỏ lặp đi lặp lại, như quy trình lỏng lẻo hay khách hàng bị bỏ quên. Đối thủ linh hoạt sẽ lấy dần từng chút. Hãy hỏi: mình đang để rơi những gì mà chưa ai nhặt lên?",
   confuse:{id:5, text:"Sấn hỏa đả kiếp chờ một khủng hoảng lớn của đối phương. Thuận thủ khiên dương nhặt những sơ hở nhỏ, thường ngày, ngay trên đường mình đang đi."}},
  {id:20, lens:"l2", name:"Hỗn thủy mô ngư", han:"混水摸鱼", literal:"Khuấy nước đục để bắt cá", group:"Hỗn chiến kế, nhóm dùng khi tình thế rối ren",
   story:"Sau trận Xích Bích năm 208, Tào Tháo thua chạy về bắc, còn Chu Du của Đông Ngô dồn sức giằng co với Tào Nhân ở Giang Lăng suốt hơn một năm. Nhân lúc hai bên mạnh đang mắc kẹt với nhau, Lưu Bị đem quân chiếm bốn quận phía nam Kinh Châu là Vũ Lăng, Trường Sa, Quế Dương và Linh Lăng, từ chỗ không có đất đứng chân trở thành một thế lực thực sự.",
   note:"Tam quốc diễn nghĩa kể thêm chuyện Gia Cát Lượng chiếm Nam Quận ngay khi Chu Du vừa đánh xong, nhưng chi tiết đó là hư cấu. Tiếng Việt có thành ngữ cùng tinh thần: đục nước béo cò.",
   mech:"Khi tình thế hỗn loạn, các bên mạnh đang vướng vào nhau và mọi thứ chưa định hình, nhanh chóng chiếm lấy những thứ chưa có chủ. Có thể khai thác hỗn loạn sẵn có, hoặc chủ động khuấy đục để đối phương mất phương hướng.",
   cond:"Có hỗn loạn thật và các bên mạnh đang bị phân tâm. Mình biết rõ mình muốn gì trong khi người khác còn rối. Hành động trước khi trật tự mới hình thành.",
   fail:"Hỗn loạn lắng xuống nhanh hơn dự tính và các bên mạnh quay sang mình. Hoặc chính mình cũng mất phương hướng trong nước đục.",
   detect:"Khi tổ chức của bạn đang rối, như lúc tái cơ cấu hay thị trường biến động, hãy để ý ai đang tranh thủ lấy những thứ chưa ai quản: khách hàng không người phụ trách, vị trí bỏ trống. Trong lúc hỗn loạn, càng phải rõ ai phụ trách việc gì.",
   confuse:{id:5, text:"Sấn hỏa đả kiếp nhắm vào khủng hoảng của một đối phương cụ thể. Hỗn thủy mô ngư tận dụng tình trạng rối ren chung, nơi ai cũng bị ảnh hưởng, để chiếm phần chưa có chủ."}},
  {id:36, lens:"l2", name:"Tẩu vi thượng sách", han:"走为上", literal:"Chạy là thượng sách", group:"Bại chiến kế, nhóm dùng khi mình đang thất thế",
   story:"Năm 431, tướng Đàn Đạo Tế nhà Lưu Tống đánh Bắc Ngụy, nhưng quân hết lương và bị quân Ngụy truy đuổi. Ban đêm, ông cho lính dùng đấu đong cát, rải một ít gạo lên trên, vừa đong vừa xướng to số lượng. Lính do thám của Ngụy tưởng quân Tống còn nhiều lương nên không dám đuổi gấp. Đàn Đạo Tế rút toàn quân về an toàn.",
   note:"Từ chuyện này mà có câu “Ba mươi sáu sách của Đàn công, chạy là thượng sách”, sau thành tên gọi của cả bộ 36 kế. Để ý rằng cuộc rút lui thành công nhờ kết hợp với một kế khác che giấu tình trạng thật.",
   mech:"Khi thế đã bất lợi rõ ràng, chủ động rút lui để bảo toàn lực, thay vì đánh đến cùng hay đầu hàng. Rút như vậy để giữ lại khả năng chiến đấu cho lúc thế tốt hơn.",
   cond:"Đánh giá thế một cách trung thực, không để cái tôi hay những gì đã bỏ ra chi phối. Có nơi để rút về. Rút có trật tự, thường kết hợp với một kế khác để che giấu.",
   fail:"Rút quá muộn, khi lực lượng đã tan rã. Rút quá sớm hoặc quá thường xuyên, khiến mất lòng tin và bỏ lỡ cơ hội. Hoặc rút lộn xộn thành tháo chạy.",
   detect:"Với chính mình: dấu hiệu nên rút là khi lý do duy nhất để tiếp tục là “đã lỡ bỏ vào quá nhiều”. Với đối phương: một cuộc rút lui có trật tự không có nghĩa là họ đã thua, đừng vội truy đuổi vào bẫy.",
   confuse:{id:21, text:"Kim thiền thoát xác là kỹ thuật rút lui kín đáo, giữ vỏ ở lại. Tẩu vi thượng sách là quyết định chiến lược rằng rút lui là lựa chọn tốt nhất lúc này."}},

  {id:13, lens:"l5", name:"Đả thảo kinh xà", han:"打草惊蛇", literal:"Đánh cỏ động rắn", group:"Công chiến kế, nhóm dùng khi chủ động tấn công",
   story:"Đời Đường, Vương Lỗ làm huyện lệnh huyện Đương Đồ, vốn tham lam vơ vét. Một lần, dân trong huyện gửi đơn tố cáo viên chủ bạ dưới quyền ông nhận hối lộ. Vương Lỗ đọc xong thì giật mình, vì những việc ấy chính ông cũng làm. Ông phê vào đơn tám chữ: “Nhữ tuy đả thảo, ngô dĩ kinh xà”, nghĩa là các ngươi tuy chỉ đánh vào cỏ, nhưng ta đã sợ như rắn.",
   note:"Thành ngữ có hai chiều nghĩa. Chiều thận trọng: tránh những động tác nhỏ khiến đối phương cảnh giác trước khi mình sẵn sàng. Chiều chủ động: cố ý tạo một tác động nhỏ để xem đối phương phản ứng ra sao.",
   mech:"Một tác động nhỏ vào vùng xung quanh có thể làm lộ, hoặc làm hoảng, mục tiêu chính. Người dùng kế hoặc tránh tác động ấy để giữ bất ngờ, hoặc cố ý tạo ra nó để buộc đối phương lộ lực lượng ẩn hay ý đồ.",
   cond:"Với chiều chủ động: phản ứng của đối phương mang lại thông tin có giá trị, và cái giá của việc làm họ cảnh giác thấp hơn giá trị thông tin đó. Với chiều thận trọng: mục tiêu lớn cần yếu tố bất ngờ.",
   fail:"Thăm dò khiến đối phương cảnh giác và chuẩn bị kỹ hơn. Hoặc đối phương đoán ra là thăm dò và cố tình phản ứng sai để đánh lừa mình.",
   detect:"Những động thái nhỏ, lẻ tẻ, không có mục đích rõ ràng từ phía đối phương: một lời đề nghị thử, một tin đồn tung ra. Hãy cân nhắc trước khi phản ứng, vì phản ứng của bạn chính là thông tin họ đang tìm.",
   confuse:{id:6, text:"Dương đông kích tây tạo đòn nhử để đánh vào nơi khác. Đả thảo kinh xà tạo tác động nhỏ để quan sát phản ứng; mục đích là thông tin chứ không phải đòn đánh."}},
  {id:14, lens:"l5", name:"Tá thi hoàn hồn", han:"借尸还魂", literal:"Mượn xác hoàn hồn", group:"Công chiến kế, nhóm dùng khi chủ động tấn công",
   story:"Cuối đời Tần, năm 208 TCN, các cuộc khởi nghĩa nổ ra khắp nơi. Theo lời khuyên của Phạm Tăng, Hạng Lương tìm được Hùng Tâm, cháu của Sở Hoài vương cũ, lúc ấy đang đi chăn dê trong dân gian, rồi lập làm Sở Hoài vương mới. Mang danh nghĩa khôi phục nước Sở, lực lượng của họ Hạng thu hút được đông đảo người Sở vốn căm ghét nhà Tần.",
   note:"Mặt trái của kế cũng hiện rõ trong câu chuyện này: về sau Hùng Tâm, khi đã thành Nghĩa Đế, có ý chí riêng, và Hạng Vũ phải giết ông, mất đi chính danh mà chính họ Hạng đã dựng lên.",
   mech:"Mượn một danh nghĩa, biểu tượng hay thứ tưởng đã chết, như danh hiệu cũ, thương hiệu cũ, một chính danh, rồi hồi sinh nó để phục vụ mục tiêu của mình. Thứ được mượn mang lại tính chính danh và lòng tin mà tự mình không tạo ra được.",
   cond:"Biểu tượng được mượn vẫn còn sức nặng trong lòng người. Mình kiểm soát được nó. Đang có một khoảng trống chính danh cần lấp.",
   fail:"Cái xác được hồi sinh có ý chí riêng và thoát khỏi kiểm soát. Hoặc người ta nhận ra danh nghĩa chỉ là cái vỏ, và lòng tin quay thành phẫn nộ.",
   detect:"Một bên mới nổi bỗng gắn mình với một danh nghĩa, biểu tượng hay thương hiệu cũ được nhiều người yêu mến. Hãy hỏi: họ thực sự kế thừa điều gì, hay chỉ mượn cái vỏ?",
   confuse:{id:29, text:"Thụ thượng khai hoa mượn vẻ ngoài để mình trông mạnh hơn. Tá thi hoàn hồn mượn chính danh để người khác tự nguyện đi theo mình."}},
  {id:16, lens:"l5", name:"Dục cầm cố túng", han:"欲擒故纵", literal:"Muốn bắt nên cố ý thả", group:"Công chiến kế, nhóm dùng khi chủ động tấn công",
   story:"Năm 225, Gia Cát Lượng đem quân bình định Nam Trung. Thủ lĩnh Mạnh Hoạch được người bản địa kính phục, nên Gia Cát Lượng muốn thu phục lòng người chứ không chỉ thắng trận. Theo sách Hán Tấn Xuân Thu, ông bắt được Mạnh Hoạch, cho xem doanh trại rồi thả về đánh tiếp, cứ thế bảy lần bắt bảy lần tha. Đến lần cuối, Mạnh Hoạch tâm phục, thề không phản nữa, và vùng Nam Trung yên ổn trong suốt thời gian Gia Cát Lượng bắc phạt.",
   note:"Con số bảy lần có thể đã được thêu dệt, và Tam quốc diễn nghĩa còn kể chi tiết hơn nhiều. Điều đáng học là mục tiêu: một hậu phương ổn định lâu dài quan trọng hơn một chiến thắng nhanh.",
   mech:"Không ép đối phương đến cùng ngay, mà nới lỏng có chủ ý để họ cạn sức, mất cảnh giác, hoặc tự nguyện quy phục. Người dùng kế chấp nhận bỏ qua chiến thắng trước mắt để có kết quả bền vững.",
   cond:"Mình đủ mạnh để bắt lại bất cứ lúc nào. Mục tiêu là sự quy phục lâu dài chứ không chỉ một chiến thắng. Đối phương có khả năng thay đổi thái độ nhờ được thả.",
   fail:"Thả rồi không bắt lại được. Đối phương coi việc được thả là dấu hiệu yếu đuối và mạnh lên. Hoặc chi phí kéo dài vượt quá lợi ích.",
   detect:"Đối phương để bạn thắng dễ dàng vài lần, hoặc bất ngờ nới lỏng sức ép. Hãy hỏi: họ được gì khi để mình đi, và sợi dây đang nằm trong tay ai?",
   confuse:{id:22, text:"Quan môn tróc tặc khóa kín mọi lối để giải quyết dứt điểm. Dục cầm cố túng cố ý chừa lối để đối phương tự kiệt sức hoặc tự quy phục."}},
  {id:17, lens:"l5", name:"Phao chuyên dẫn ngọc", han:"抛砖引玉", literal:"Ném gạch dẫn ngọc", group:"Công chiến kế, nhóm dùng khi chủ động tấn công",
   story:"Năm 700 TCN, nước Sở đánh nước Giảo nhưng thành Giảo kiên cố khó hạ. Khuất Hà hiến kế: cho những người đốn củi không có quân hộ vệ vào núi. Quân Giảo ra bắt được ba mươi người, hôm sau thấy dễ ăn, kéo ra đông hơn để bắt tiếp. Quân Sở phục sẵn chặn đường về, đại phá quân Giảo, và nước Giảo phải ký giao ước đầu hàng ngay dưới chân thành.",
   note:"Câu chuyện được chép trong Tả truyện. Hình ảnh của tên kế: ném ra một viên gạch rẻ tiền để đổi về một viên ngọc quý.",
   mech:"Bỏ ra một thứ nhỏ, rẻ để làm mồi, khiến đối phương hành động theo hướng mình muốn hoặc đưa ra thứ có giá trị lớn hơn nhiều.",
   cond:"Mồi đủ hấp dẫn và trông như thật. Đối phương có lòng tham hoặc nhu cầu tương ứng. Mình kiểm soát được bước tiếp theo sau khi họ cắn câu.",
   fail:"Đối phương lấy mồi rồi không làm gì thêm. Mồi quá rẻ nên bị nhận ra. Hoặc mồi quá đắt, mất nhiều hơn được.",
   detect:"Một món lợi nhỏ đến dễ dàng một cách bất thường, nhất là khi bước tiếp theo đòi bạn đặt cược nhiều hơn. Hãy hỏi: ai đã đặt món lợi này ở đây, và họ muốn mình làm gì tiếp theo?",
   confuse:{id:11, text:"Lý đại đào cương hy sinh một phần để bảo toàn phần quan trọng hơn của chính mình. Phao chuyên dẫn ngọc bỏ ra một thứ nhỏ làm mồi để lấy thứ lớn từ đối phương."}},
  {id:26, lens:"l5", name:"Chỉ tang mạ hòe", han:"指桑骂槐", literal:"Chỉ cây dâu mắng cây hòe", group:"Tịnh chiến kế, nhóm dùng trong quan hệ liên minh và tranh quyền",
   story:"Tôn Vũ đến yết kiến Ngô vương Hạp Lư. Vua muốn thử tài, giao cho ông luyện 180 cung nữ. Tôn Vũ chia làm hai đội, cử hai ái phi của vua làm đội trưởng, giảng giải hiệu lệnh nhiều lần. Đến khi đánh trống ra lệnh, các cung nữ chỉ cười. Tôn Vũ cho rằng lệnh đã rõ mà không theo là lỗi của người chỉ huy, bèn hạ lệnh chém hai đội trưởng, mặc vua xin tha. Từ đó cả đội răm rắp theo lệnh.",
   note:"Câu chuyện được chép trong Sử ký. Hai ái phi không phải người cười duy nhất; họ bị chọn vì hình phạt dành cho họ gửi thông điệp rõ nhất tới tất cả những người còn lại.",
   mech:"Phê phán hoặc trừng phạt một đối tượng để gửi thông điệp tới đối tượng khác mà mình không tiện, hoặc không muốn, nhắm trực tiếp. Đây là răn đe gián tiếp.",
   cond:"Người nhận thông điệp hiểu được ẩn ý. Đối tượng bị chỉ vào có liên hệ rõ với thông điệp. Mình có quyền hoặc chính danh để hành động.",
   fail:"Thông điệp không đến được người cần nghe, hoặc bị hiểu sai. Người bị chỉ vào thấy bất công và oán giận. Hoặc ai cũng nhận ra là nói bóng gió, và mình mất uy tín vì thiếu thẳng thắn.",
   detect:"Một lời phê phán hay hình phạt nặng tay bất thường với một người nhỏ. Hãy hỏi: thông điệp này thực sự được gửi cho ai?",
   confuse:{id:3, text:"Tá đao sát nhân dùng người khác để ra tay với đối phương. Chỉ tang mạ hòe tự mình ra tay với một người để gửi thông điệp cho người khác."}},
  {id:31, lens:"l5", name:"Mỹ nhân kế", han:"美人计", literal:"Kế dùng người đẹp", group:"Bại chiến kế, nhóm dùng khi mình đang thất thế",
   story:"Sau khi thua nước Ngô, Việt vương Câu Tiễn theo kế của Văn Chủng và Phạm Lãi, dâng người đẹp Tây Thi cùng nhiều của cải cho Ngô vương Phù Sai. Phù Sai say mê hưởng lạc, xây cung điện tốn kém, xa rời chính sự. Khi đại thần Ngũ Tử Tư nhiều lần can gián, Phù Sai còn ép ông phải tự sát. Trong khi đó, nước Việt nằm gai nếm mật, gây dựng lại lực lượng.",
   note:"Câu chuyện Tây Thi đến từ các sách đời sau như Ngô Việt Xuân Thu, không có trong Sử ký, nên nhiều chi tiết có thể là truyền thuyết. Nghĩa rộng của kế không chỉ là sắc đẹp mà là mọi thứ đánh vào ham muốn: tiện nghi, quà cáp, lời tâng bốc.",
   mech:"Đánh vào ham muốn của người đứng đầu để làm họ sao nhãng, mất ý chí và phán đoán. Kế nhắm vào sự tỉnh táo của người lãnh đạo, thứ mà binh lực không bảo vệ được.",
   cond:"Đối phương có điểm yếu ham muốn rõ ràng. Món quà đến qua một kênh hợp lý, không bị nghi ngờ. Mình đủ kiên nhẫn chờ hiệu quả dài hạn.",
   fail:"Người nhận vẫn tỉnh táo, hoặc có người can gián và được lắng nghe. Kế bị lộ gây phản ứng dữ dội.",
   detect:"Quà cáp, đặc quyền và lời tâng bốc ngày càng nhiều mà không rõ lý do. Quan trọng hơn: bạn dần thấy xa cách với những người hay nói thật với mình.",
   confuse:{id:10, text:"Tiếu lý tàng đao dùng thiện chí để đối phương hạ phòng bị cho một lần ra tay. Mỹ nhân kế bào mòn ý chí và phán đoán của đối phương qua một thời gian dài."}},
  {id:34, lens:"l5", name:"Khổ nhục kế", han:"苦肉计", literal:"Kế tự làm mình đau", group:"Bại chiến kế, nhóm dùng khi mình đang thất thế",
   story:"Năm 208, trước trận Xích Bích, lão tướng Đông Ngô Hoàng Cái gửi thư cho Tào Tháo xin đầu hàng. Tào Tháo tin, hẹn ngày đón. Đến hẹn, Hoàng Cái đem hơn mười chiến thuyền chất đầy củi khô tẩm dầu, cắm cờ hàng tiến đến. Khi gần trại Tào, quân Ngô châm lửa, thuyền lửa lao vào hạm đội Tào đang nối liền nhau, mở đầu cho thất bại lớn nhất đời Tào Tháo.",
   note:"Chính sử chỉ ghi Hoàng Cái trá hàng. Chi tiết Chu Du sai đánh Hoàng Cái một trận đòn nhừ tử để Tào Tháo tin là thật, thứ làm nên tên tuổi của khổ nhục kế, là của Tam quốc diễn nghĩa.",
   mech:"Tự gây tổn thất thật cho mình hoặc người của mình để một câu chuyện giả trở nên đáng tin, khiến đối phương hạ phòng bị. Con người thường không nghi ngờ người đã tự làm hại chính mình.",
   cond:"Tổn thất phải thật và đủ nặng để thuyết phục. Đối phương có sẵn lý do để tin vào mâu thuẫn nội bộ bên mình. Giá trị thu được lớn hơn tổn thất bỏ ra.",
   fail:"Đối phương vẫn kiểm chứng hoặc đề phòng người mới đến dù câu chuyện thảm đến đâu. Tổn thất quá lớn không bù lại được. Bị lộ thì mất cả hai.",
   detect:"Một người tìm đến bạn với câu chuyện bị phía bên kia đối xử tệ, kèm bằng chứng tổn thương, và đề nghị giúp bạn chống lại họ. Thông cảm thì được, nhưng hãy giới hạn quyền tiếp cận cho đến khi kiểm chứng xong.",
   confuse:{id:33, text:"Phản gián kế lợi dụng kênh tin có sẵn của đối phương. Khổ nhục kế cài người của mình vào bằng một câu chuyện được trả giá bằng tổn thất thật."}},

  {id:2, lens:"l6", name:"Vây Ngụy cứu Triệu", han:"围魏救赵", literal:"Vây nước Ngụy để cứu nước Triệu", group:"Thắng chiến kế, nhóm dùng khi mình đang có ưu thế",
   story:"Năm 354 TCN, nước Ngụy vây Hàm Đan, kinh đô nước Triệu. Triệu cầu cứu nước Tề. Tề cử Điền Kỵ làm tướng, Tôn Tẫn làm quân sư. Điền Kỵ muốn kéo quân thẳng đến Hàm Đan, nhưng Tôn Tẫn khuyên đánh vào Đại Lương, kinh đô nước Ngụy, lúc này đang trống vì tinh binh Ngụy dồn cả ra ngoài. Tướng Ngụy là Bàng Quyên buộc phải bỏ vây, hành quân gấp về cứu, và bị quân Tề phục kích đánh bại ở Quế Lăng.",
   note:"",
   mech:"Không đối đầu nơi đối phương đang mạnh, mà đe dọa một điểm họ coi trọng hơn mục tiêu hiện tại. Đối phương buộc phải rời thế chủ động và di chuyển theo nhịp của mình, còn mình được chọn chiến trường.",
   cond:"Đối phương có một điểm yếu mà họ quý hơn mục tiêu đang theo đuổi. Mối đe dọa của mình phải là thật. Mình đủ cơ động để đánh tới đó.",
   fail:"Đối phương hạ được mục tiêu trước khi kịp quay về. Hoặc họ không thật sự coi trọng điểm bị đe dọa, nên lờ đi.",
   detect:"Đang dồn sức vào một việc thì bị gây áp lực bất ngờ ở chỗ khác. Hãy hỏi: nguy cơ này thật đến đâu, hay ai đó đang kéo mình rời khỏi việc đang làm?",
   confuse:{id:15, text:"Điệu hổ ly sơn kéo đối phương rời vị trí bằng mồi. Vây Ngụy cứu Triệu buộc họ rời đi bằng cách đe dọa thứ họ không thể để mất."}},
  {id:18, lens:"l6", name:"Cầm tặc cầm vương", han:"擒贼擒王", literal:"Bắt giặc phải bắt tướng", group:"Công chiến kế, nhóm dùng khi chủ động tấn công",
   story:"Năm 757, Trương Tuần giữ thành Thư Dương trước quân phản loạn của Doãn Tử Kỳ. Ông muốn bắn hạ chủ tướng địch nhưng không biết ai là Doãn Tử Kỳ giữa đám đông. Trương Tuần bèn cho bắn những mũi tên bằng cành cỏ. Lính địch nhặt được, tưởng quân trong thành đã hết tên, mừng rỡ chạy về báo cho chủ tướng. Nhờ vậy quân Đường nhận ra Doãn Tử Kỳ, và tướng Nam Tễ Vân bắn trúng mắt trái ông ta. Quân địch phải rút lui.",
   note:"Tên kế lấy từ thơ Đỗ Phủ: “Xạ nhân tiên xạ mã, cầm tặc tiên cầm vương”, tức là bắn người thì bắn ngựa trước, bắt giặc thì bắt tướng trước. Đây cũng là Trương Tuần trong kế Vô trung sinh hữu.",
   mech:"Tập trung vào trung tâm chỉ huy hoặc điểm then chốt mà cả hệ thống phụ thuộc. Khi nó sụp, phần còn lại tự tan rã. Đánh vào đầu não thay vì tiêu hao từng bộ phận.",
   cond:"Đối phương thực sự phụ thuộc vào một trung tâm. Xác định đúng trung tâm thật chứ không phải thứ trông như trung tâm. Mình tiếp cận được nó.",
   fail:"Hệ thống của đối phương phân tán, không có đầu não duy nhất. Trung tâm thật được che giấu. Hoặc đánh vào đầu não khiến phần còn lại đoàn kết lại vì phẫn nộ.",
   detect:"Với tổ chức của chính bạn: nếu một người hay một hệ thống ngừng hoạt động mà mọi thứ tê liệt, đó là điểm đối thủ sẽ nhắm tới. Hãy xây phương án dự phòng cho nó.",
   confuse:{id:19, text:"Cầm tặc cầm vương đánh vào đầu não chỉ huy. Phủ để trừu tân đánh vào nguồn cung nuôi sống cả hệ thống."}},
  {id:19, lens:"l6", name:"Phủ để trừu tân", han:"釜底抽薪", literal:"Rút củi dưới đáy nồi", group:"Hỗn chiến kế, nhóm dùng khi tình thế rối ren",
   story:"Năm 200, ở Quan Độ, quân Viên Thiệu đông hơn hẳn quân Tào Tháo, hai bên giằng co nhiều tháng và quân Tào sắp cạn lương. Hứa Du, mưu sĩ của Viên Thiệu, bỏ sang hàng Tào và báo rằng kho lương của Viên Thiệu đặt ở Ô Sào, phòng bị lỏng lẻo. Tào Tháo đích thân dẫn năm nghìn quân đi đêm tập kích, đốt sạch kho lương. Quân Viên hoang mang, nhiều tướng đầu hàng, và đại quân tan rã.",
   note:"Giải ngữ gốc của kế viết: không đánh vào sức mạnh của địch, mà tiêu hao cái thế của nó. Nước đang sôi dữ dội đến đâu cũng sẽ nguội khi không còn củi.",
   mech:"Không đối đầu với sức mạnh đang sôi sục, mà triệt tiêu nguồn tạo ra sức mạnh ấy: lương thực, tài chính, nguồn nhân lực hay động cơ. Đánh vào nguồn chứ không đánh vào biểu hiện.",
   cond:"Xác định đúng nguồn lực then chốt. Nguồn lực đó tập trung và tiếp cận được. Đối phương không có nguồn thay thế nhanh.",
   fail:"Đối phương có nhiều nguồn dự phòng. Ý đồ bị lộ và họ tăng cường bảo vệ nguồn lực. Hoặc hiệu quả đến quá chậm so với áp lực mình đang chịu.",
   detect:"Nguồn lực của bạn có đang tập trung ở một chỗ không: một nhà cung cấp, một khách hàng lớn, một nguồn vốn? Đó là đáy nồi của bạn. Hãy đa dạng hóa trước khi ai đó rút củi.",
   confuse:{id:18, text:"Cầm tặc cầm vương đánh vào đầu não ra quyết định. Phủ để trừu tân đánh vào nguồn cung nuôi sống cả hệ thống."}},
  {id:25, lens:"l6", name:"Thâu lương hoán trụ", han:"偷梁换柱", literal:"Trộm xà thay cột", group:"Tịnh chiến kế, nhóm dùng trong quan hệ liên minh và tranh quyền",
   story:"Năm 210 TCN, Tần Thủy Hoàng mất đột ngột trên đường tuần du, để lại chiếu thư truyền ngôi cho con trưởng là Phù Tô. Hoạn quan Triệu Cao cùng thừa tướng Lý Tư giấu tin vua mất, sửa lại chiếu thư: lập con thứ là Hồ Hợi làm vua, đồng thời ban chiếu bắt Phù Tô tự sát. Mọi nghi thức bên ngoài vẫn như cũ, nhưng người nắm thiên hạ đã bị thay. Chỉ vài năm sau, nhà Tần sụp đổ.",
   note:"Câu chuyện được chép trong Sử ký. Kết cục của nhà Tần cũng cho thấy điểm gãy của kế: cột thay vào yếu hơn cột cũ thì cả ngôi nhà sụp.",
   mech:"Âm thầm thay những bộ phận cốt lõi của một cấu trúc, như con người, luật lệ hay nội dung, trong khi giữ nguyên vẻ ngoài, để nó vận hành theo ý mình. Người khác vẫn thấy ngôi nhà cũ, nhưng xà và cột đã khác.",
   cond:"Mình tiếp cận được phần lõi. Vẻ ngoài và các thủ tục bề mặt được giữ nguyên. Ít người kiểm tra trực tiếp phần lõi.",
   fail:"Có người kiểm tra trực tiếp phần lõi. Người bị thay thế lên tiếng. Hoặc cấu trúc sụp đổ vì phần thay vào yếu hơn.",
   detect:"Tên gọi và hình thức vẫn như cũ, nhưng điều khoản, người ra quyết định hay tiêu chí đã âm thầm thay đổi. Hãy đọc lại phần lõi thay vì tin vào cái nhãn.",
   confuse:{id:30, text:"Phản khách vi chủ là quá trình từng bước đi từ vị trí khách lên vị trí chủ. Thâu lương hoán trụ là thay ruột của cấu trúc trong khi giữ nguyên vỏ."}},
  {id:30, lens:"l6", name:"Phản khách vi chủ", han:"反客为主", literal:"Khách trở thành chủ", group:"Tịnh chiến kế, nhóm dùng trong quan hệ liên minh và tranh quyền",
   story:"Năm 211, Lưu Chương, chủ Ích Châu, lo sợ Trương Lỗ ở Hán Trung đánh vào nên mời Lưu Bị đem quân vào đất Thục giúp sức. Lưu Bị đến với tư cách khách, được tiếp đãi long trọng và đóng quân ở Gia Manh. Ông không vội đánh Trương Lỗ, mà ra sức thu phục lòng người và củng cố lực lượng tại chỗ. Năm 212, Lưu Bị trở mặt, tiến quân về Thành Đô. Năm 214, Lưu Chương đầu hàng, và vị khách trở thành chủ nhân Ích Châu.",
   note:"",
   mech:"Từ vị trí khách, tức là được mời, được nhờ, hoặc đang phụ thuộc, từng bước nắm lấy những điểm then chốt cho đến khi đảo ngược quan hệ và trở thành chủ.",
   cond:"Có cơ hội được mời vào bên trong. Chủ nhà yếu hoặc đang cần mình. Mình đủ kiên nhẫn đi từng bước: tạo chỗ đứng, nắm điểm then chốt, rồi mới lật thế.",
   fail:"Chủ nhà cảnh giác, giới hạn phạm vi và thời gian của khách. Mình nóng vội để lộ ý đồ quá sớm. Hoặc bị coi là kẻ phản bội và mất chính danh.",
   detect:"Một đối tác, nhà tư vấn hay nhà đầu tư được mời vào để giúp, nhưng dần nắm những điểm then chốt: tài chính, khách hàng, quyết định nhân sự. Hãy hỏi: nếu họ rời đi ngày mai, mình còn tự vận hành được không?",
   confuse:{id:24, text:"Giả đạo phạt Quắc vào nhờ mượn đường rồi đánh chiếm nhanh. Phản khách vi chủ vào với tư cách khách và giành quyền từ từ từ bên trong."}},
  {id:35, lens:"l6", name:"Liên hoàn kế", han:"连环计", literal:"Kế nối vòng", group:"Bại chiến kế, nhóm dùng khi mình đang thất thế",
   story:"Ở Xích Bích năm 208, quân Tào phần lớn là người phương bắc, không quen sóng nước, nên các chiến thuyền được neo nối đầu đuôi vào nhau. Chu Du và Hoàng Cái nhận ra hạm đội nối liền như vậy rất dễ cháy lan. Một chuỗi nước đi nối tiếp nhau diễn ra: Hoàng Cái gửi thư trá hàng để được tiếp cận, thuyền lửa chờ đúng ngày gió đông nam, lửa từ các thuyền đi đầu lan khắp hạm đội đang bị chính nó trói buộc, rồi quân Tôn Lưu đánh tràn trên bộ.",
   note:"Tam quốc diễn nghĩa kể Bàng Thống cố ý khuyên Tào Tháo xích thuyền lại với nhau. Chi tiết ấy là hư cấu, nhưng nó minh họa đúng giải ngữ gốc của kế: “Sử kỳ tự lụy”, khiến đối phương tự trói buộc mình.",
   mech:"Nối nhiều kế thành một chuỗi, kế trước tạo điều kiện cho kế sau. Chuỗi thường bắt đầu bằng việc khiến đối phương tự trói buộc mình, làm giảm khả năng phản ứng, rồi mới ra đòn quyết định.",
   cond:"Hiểu rõ từng kế trong chuỗi và điều kiện của chúng. Trình tự hợp lý, mắt xích trước thực sự mở đường cho mắt xích sau. Đủ thời gian và nguồn lực để thực hiện hết chuỗi.",
   fail:"Một mắt xích hỏng kéo cả chuỗi sụp. Chuỗi quá phức tạp nên khó kiểm soát. Hoặc đối phương phá đúng mắt xích then chốt.",
   detect:"Nhiều sự kiện tưởng rời rạc lại cùng đẩy bạn về một hướng, và mỗi bước bạn đi lại khiến bước sau khó rút lui hơn. Hãy nhìn cả chuỗi, đừng chỉ nhìn từng mắt xích.",
   confuse:{id:28, text:"Thượng ốc trừu thê là một cái bẫy đơn: đưa mồi rồi rút thang. Liên hoàn kế nối nhiều kế với nhau, và cái bẫy thường là việc đối phương tự trói chính mình."}}

];
